    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <path d="M4.5 4.5 L13.5 4.5 L19.5 10.5 L12 18 L4.5 10.5 Z" /><circle cx="9.5" cy="9.5" r="1.3" />
    </svg>
